const state = $('Process Quality1').first().json;
const response = $input.first().json;
const paperContent = response.candidates?.[0]?.content?.parts?.[0]?.text || '';

state.artifacts.finalPaper = paperContent;
state.currentPhase = 'paper_complete';
state.agentLogs.push({ agent: 'Agent 8', status: 'done', model: 'Gemini Pro' });
state.modelsUsed.push('Gemini Pro');

return [{ json: state }];

// Generate PDF-ready HTML from Markdown
const state = $input.first().json;
const markdown = state.artifacts.finalPaper;
const topic = state.topic;
const date = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

// Simple markdown to HTML conversion
function mdToHtml(md) {
  return md
    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
    .replace(/^# (.*$)/gim, '<h1>$1</h1>')
    .replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*)\*/gim, '<em>$1</em>')
    .replace(/^- (.*$)/gim, '<li>$1</li>')
    .replace(/^\d+\. (.*$)/gim, '<li>$1</li>')
    .replace(/```([\s\S]*?)```/gim, '<pre><code>$1</code></pre>')
    .replace(/`([^`]+)`/gim, '<code>$1</code>')
    .replace(/\n/gim, '<br>');
}

const htmlContent = mdToHtml(markdown);

const pdfHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Research Paper: ${topic}</title>
  <style>
    @page { margin: 2cm; size: A4; }
    @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }

    * { box-sizing: border-box; }

    body {
      font-family: 'Times New Roman', Times, serif;
      font-size: 12pt;
      line-height: 1.6;
      color: #1a1a1a;
      max-width: 800px;
      margin: 0 auto;
      padding: 40px;
      background: white;
    }

    .header {
      text-align: center;
      border-bottom: 2px solid #2563eb;
      padding-bottom: 20px;
      margin-bottom: 30px;
    }

    .header h1 {
      font-size: 24pt;
      color: #1e3a5f;
      margin-bottom: 10px;
    }

    .header .meta {
      font-size: 10pt;
      color: #666;
    }

    .badge {
      display: inline-block;
      background: linear-gradient(135deg, #2563eb, #7c3aed);
      color: white;
