      margin: 5px 2px;
    }

    h1 { font-size: 18pt; color: #1e3a5f; margin-top: 30px; border-bottom: 1px solid #ddd; padding-bottom: 5px; }
    h2 { font-size: 14pt; color: #2563eb; margin-top: 25px; }
    h3 { font-size: 12pt; color: #444; margin-top: 20px; }

    p, li { text-align: justify; }

    ul, ol { margin-left: 20px; }
    li { margin-bottom: 5px; }

    pre {
      background: #f5f5f5;
      border: 1px solid #ddd;
      border-radius: 4px;
      padding: 15px;
      overflow-x: auto;
      font-family: 'Courier New', monospace;
      font-size: 10pt;
    }

    code {
      background: #f0f0f0;
      padding: 2px 6px;
      border-radius: 3px;
      font-family: 'Courier New', monospace;
      font-size: 10pt;
    }

