    }

    .print-btn:hover { transform: scale(1.05); }

    @media print { .print-btn { display: none; } }
  </style>
</head>
<body>
  <button class="print-btn" onclick="window.print()">📄 Save as PDF</button>

  <div class="header">
    <h1>Research Paper</h1>
    <p style="font-size: 16pt; color: #333;">${topic}</p>
    <p class="meta">Generated: ${date}</p>
    <div>
      <span class="badge">🧠 Groq LLaMA 3.3</span>
      <span class="badge">✨ Gemini Pro</span>
      <span class="badge">🤖 8 AI Agents</span>
    </div>
  </div>

  <div class="content">
    ${htmlContent}
  </div>

  <div class="footer">
    <p>Generated by Multi-Agent Research System v9 (Hybrid)</p>
    <p>Powered by n8n • Groq LLaMA 3.3 • Google Gemini Pro</p>
  </div>
</body>
</html>`;

state.artifacts.pdfHtml = pdfHtml;
state.currentPhase = 'pdf_ready';
state.endTime = new Date().toISOString();

const startTime = new Date(state.startTime);
const endTime = new Date(state.endTime);
const executionSeconds = Math.round((endTime - startTime) / 1000);

return [{
  json: {
    success: true,
    content: state.artifacts.finalPaper,
    pdfHtml: pdfHtml,
    metadata: {
      topic: state.topic,
      startTime: state.startTime,
      endTime: state.endTime,
      executionTimeSeconds: executionSeconds,
      agentsExecuted: 8,
      modelsUsed: ['Groq LLaMA 3.3', 'Gemini 1.5 Flash', 'Gemini 1.5 Pro'],
      hybridMode: true
    }
  }
}];

const topic = $input.first().json.body?.topic || $input.first().json.topic;

if (!topic || topic.trim().length < 3) {
  throw new Error('Invalid topic: Please provide a research topic with at least 3 characters');
}

const researchState = {
  topic: topic.trim(),
  startTime: new Date().toISOString(),
  currentPhase: 'initialization',
  artifacts: {
    keywords: [],
    literature: [],
    literatureReview: '',
    gaps: '',
    methodology: '',
    datasetPlan: '',
    results: '',
    analysis: '',
    finalPaper: '',
    pdfHtml: ''
  },
  agentLogs: [],
  modelsUsed: []
};

return [{ json: researchState }];

const state = $('Initialize State1').first().json;
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';

let keywords;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  keywords = jsonMatch ? JSON.parse(jsonMatch[0]) : {
    primaryKeywords: [state.topic],
    searchQueries: [state.topic + ' research']
  };
} catch (e) {
  keywords = { primaryKeywords: [state.topic], searchQueries: [state.topic + ' research'] };
}

state.artifacts.keywords = keywords;
state.currentPhase = 'keywords_complete';
state.agentLogs.push({ agent: 'Agent 1', status: 'done', model: 'Groq LLaMA' });
state.modelsUsed.push('Groq');

return [{ json: state }];

const state = $('Parse Keywords1').first().json;
const searchResponse = $input.first().json;

const results = searchResponse.RelatedTopics || [];
state.artifacts.literature = results.slice(0, 8).map((item, idx) => ({
  id: idx + 1,
  text: item.Text || '',
  url: item.FirstURL || ''
}));
state.currentPhase = 'search_complete';
state.agentLogs.push({ agent: 'Web Search', status: 'done' });

return [{ json: state }];

